# =============================================================================
# mc_i18n.py — MediaClinic interface texts in English, Portuguese (Brazil) and Spanish
# Version: 0.20.0                                              ### NEW v0.20.0 UI1a ###
#
# Pure module (no I/O, no Tk, no Windows call): the catalogs are plain dicts and
# the language is chosen by the main script before the first widget is built.
#   t(key, **values)      the text of *key* in the current language
#   tn(key, n, **values)  the plural form of *key* for the number n (CLDR rules)
#   set_language(code)    "en" | "pt_BR" | "es"   (anything else → English)
#   current()             the current code
#   pick_language(stored, windows_locale)   the code to use at start
# Keys are stable names (menu.tools.auto_repair, health.title_mismatch …), never
# the English text.  A missing key falls back to English and is reported once
# through the hook the main script installs (app.log); never a crash, never a
# raw key on screen (an unknown key in every catalog returns the key's last part
# only through the fallback text given by the caller, else the key itself).
# Plural keys hold a dict {"one": …, "other": …}.  English and Spanish use "one"
# for 1 only; Portuguese (Brazil) uses it for 0 and 1.
# Spanish is neutral Latin American (usted, "computadora", "archivo").
# =============================================================================

LANGUAGES = ("en", "pt_BR", "es")
