CATALOGS = {"en": EN, "pt_BR": PT_BR, "es": ES}

_state = {"lang": "en"}
_missing_hook = [None]          # the main script sets a function(lang, key) that logs once
_reported = set()


def set_language(code):
    """Use *code* ("en", "pt_BR", "es"); anything else gives English. Returns the code used."""
    _state["lang"] = code if code in CATALOGS else "en"
    return _state["lang"]


def current():
    return _state["lang"]


def set_missing_hook(fn):
    """fn(lang, key) is called once per missing (lang, key)."""
    _missing_hook[0] = fn


def _lookup(key):
    lang = _state["lang"]
    cat = CATALOGS.get(lang, EN)
    if key in cat:
        return cat[key]
    if (lang, key) not in _reported:
        _reported.add((lang, key))
        if _missing_hook[0]:
            try:
                _missing_hook[0](lang, key)
            except Exception:
                pass
    return EN.get(key, key)


def _fmt(s, values):
    try:
        return s.format(**values) if values else s
    except (KeyError, IndexError, ValueError):
        return s


def t(key, **values):
    """The text of *key* in the current language, with {placeholders} filled."""
    s = _lookup(key)
    if isinstance(s, dict):
        s = s.get("other", "")
    return _fmt(s, values)


def plural_form(n, lang=None):
    """"one" or "other" for the number n (CLDR: en / es one = 1; pt_BR one = 0 and 1)."""
    lang = lang or _state["lang"]
    try:
        whole = float(n) == int(float(n))
        v = int(float(n))
    except (TypeError, ValueError):
        return "other"
    if lang == "pt_BR":
        return "one" if whole and v in (0, 1) else "other"
    return "one" if whole and v == 1 else "other"


def tn(key, n, as_text=None, **values):
    """The plural text of *key* for the number n; {n} is filled with n, or with *as_text* when the caller gives the
    number already formatted (e.g. num(n))."""
    s = _lookup(key)
    if isinstance(s, dict):
        s = s.get(plural_form(n)) or s.get("other", "")
    return _fmt(s, dict(values, n=n if as_text is None else as_text))


def num(n, decimals=None, lang=None):                             ### NEW v0.20.0 UI1c ###
    """A number as shown on screen: "1,204" / "7.5" in English, "1.204" / "7,5" in Portuguese and Spanish (plan UI1
    point 6). *decimals* None: integers get thousands separators, floats keep their own digits. Never used for a
    value written into a file (NFO / XML ratings keep the dot)."""
    lang = lang or _state["lang"]
    try:
        if decimals is None:
            s = f"{n:,}" if isinstance(n, int) and not isinstance(n, bool) else (
                f"{n:,.{max(0, len(repr(float(n)).split('.')[1]) if '.' in repr(float(n)) else 0)}f}"
                if isinstance(n, float) else str(n))
        else:
            s = f"{float(n):,.{decimals}f}"
    except (TypeError, ValueError):
        return str(n)
    if lang in ("pt_BR", "es"):
        s = s.translate({ord(","): ".", ord("."): ","})
    return s


def has(key):                                                     ### NEW v0.20.0 UI1c ###
    """True when *key* is in the English catalog (the reference)."""
    return key in EN


def windows_language(locale_name):
    """The interface code for a Windows locale name ("pt-BR", "es-MX", "en-US" …): any Portuguese → pt_BR,
    any Spanish → es, anything else (or nothing) → en."""
    base = (locale_name or "").replace("_", "-").split("-")[0].lower()
    return {"pt": "pt_BR", "es": "es"}.get(base, "en")


def pick_language(stored, windows_locale):
    """The code to use at start: the stored choice when valid; no choice (None / "") follows Windows;
    a broken stored value gives English."""
    if stored in (None, ""):
        return windows_language(windows_locale)
    if not isinstance(stored, str):                              # v0.20.0 AU7: ["pt_BR"] in settings.json crashed the start
        return "en"
    return stored if stored in CATALOGS else "en"


def check_catalogs():
    """Problems in the catalogs (for the tests): missing / extra keys, empty values, different placeholders."""
    import string
    problems = []

    def fields(v):
        vs = v.values() if isinstance(v, dict) else [v]
        return {f for s in vs for _l, f, _s, _c in string.Formatter().parse(s) if f}

    for lang, cat in CATALOGS.items():
        if lang == "en":
            continue
        for k in EN.keys() - cat.keys():
            problems.append(f"{lang}: missing {k}")
        for k in cat.keys() - EN.keys():
            problems.append(f"{lang}: extra {k}")
        for k in EN.keys() & cat.keys():
            v, e = cat[k], EN[k]
            if isinstance(e, dict) != isinstance(v, dict):
                problems.append(f"{lang}: {k} plural / plain differs")
            elif not (all(v.values()) if isinstance(v, dict) else v):
                problems.append(f"{lang}: {k} empty")
            elif fields(v) != fields(e):
                problems.append(f"{lang}: {k} placeholders {sorted(fields(v))} != {sorted(fields(e))}")
    return problems
